#!/usr/bin/env python3
# showhow-v18b-prodline.py — เขียนบรรทัด "สินค้า" ของบอร์ดใหม่ให้สั้นลง 176 ตัวอักษรแต่ได้ล็อกอุปกรณ์เพิ่ม (2026-09-21)
# ทำไม: v18 เติมล็อกอุปกรณ์ดื้อ ๆ แล้ว prompt ทะลุเพดาน 3,900 (สูงสุด 4,015 · ทะลุ 84/10,800 คู่ผสมบทจริง)
# ที่ตัด = คำซ้ำในบรรทัดเดียวกัน: "ห้ามเปลี่ยนสี ทรง สัดส่วน…" กับ "เก็บรูปทรง สีตัวขวด/ด้าม…ให้เป๊ะ" พูดเรื่องเดียวกัน 2 รอบ
#          · "ห้ามวาดใหม่หรือเป็นการ์ตูน" ซ้ำกับบรรทัดภาพถ่ายด้านบนที่ห้ามการ์ตูน/เวกเตอร์/3D อยู่แล้ว
import json, os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
P = os.path.join(HERE, '..', 'showhow-dev.json')
OLD = ('สินค้า = ของจริงตามรูปที่แนบ (หลายชิ้น = ชิ้นละรูป): ห้ามเปลี่ยนสี ทรง สัดส่วน ฉลาก โลโก้ จำนวน ห้ามวาดใหม่หรือเป็นการ์ตูน · มุมที่รูปไม่มีให้ใช้มุมใกล้สุด · **เก็บรูปทรง สีตัวขวด/ด้าม ฉลาก โลโก้ และสัดส่วนตามรูปให้เป๊ะ** ถ้ารูปเป็นแพ็กหลายชิ้นหรือมีป้ายโปรโมชันทับ ให้วาดชิ้นเดียวโดยคงฉลากและสีเดิม เอาเฉพาะป้ายโปรโมชันกับพลาสติกหุ้มออก (ห้ามเปลี่ยนเป็นขวดหรือแปรงทรงอื่น) · **อุปกรณ์ทุกชิ้นต้องเป็นรุ่นเดียวกับรูปทุกช่อง รวมด้าม ความยาวด้าม ทรงหัว สีขนแปรง — ในรูปมีด้ามยาวต้องมีด้ามยาวทุกช่อง ห้ามย่อเป็นแปรงมือ** · ห้ามลอกฉากหลังหรือของประกอบจากรูป · **ช่องไหนมีสินค้าอยู่ในเฟรม ต้องเป็นสินค้าตามรูปที่แนบเท่านั้น ห้ามคิดขวด กล่อง แปรง หรือแบรนด์อื่นขึ้นมาเองแม้บทช่องนั้นไม่ได้พูดถึงสินค้า**')
NEW = ('สินค้า = ของจริงตามรูปที่แนบ (หลายชิ้น = ชิ้นละรูป): **ทุกช่องต้องเก็บทรง สี ฉลาก โลโก้ สัดส่วน จำนวน และด้าม/ความยาวด้าม/สีขนแปรง ตามรูปให้เป๊ะ ในรูปมีด้ามยาวต้องมีด้ามยาว ห้ามย่อเป็นแปรงมือ** · มุมที่รูปไม่มีให้ใช้มุมใกล้สุด · รูปเป็นแพ็กหลายชิ้นหรือมีป้ายโปรโมชันทับ ให้วาดชิ้นเดียว คงฉลากและสีเดิม เอาออกเฉพาะป้ายโปรโมชันกับพลาสติกหุ้ม (ห้ามเปลี่ยนทรง) · ห้ามลอกฉากหลังหรือของประกอบจากรูป · **ช่องไหนมีสินค้าในเฟรม ต้องเป็นสินค้าตามรูปเท่านั้น ห้ามคิดขวด กล่อง แปรง หรือแบรนด์อื่นขึ้นมาเองแม้บทช่องนั้นไม่ได้พูดถึง**')
raw = open(P, encoding='utf-8').read()
if NEW in raw: print('· มี v18b แล้ว ข้าม'); sys.exit(0)
s = json.dumps(json.loads(raw), ensure_ascii=False)
n = s.count(OLD); assert n == 6, f'เจอบรรทัดสินค้า {n} จุด (คาด 6)'
open(P, 'w', encoding='utf-8').write(json.dumps(json.loads(s.replace(OLD, NEW)), ensure_ascii=False, indent=1) + ('\n' if raw.endswith('\n') else ''))
G = os.path.join(HERE, 'showhow-v9-board-collage.py'); g = open(G, encoding='utf-8').read()
assert g.count(OLD) == 1
open(G, 'w', encoding='utf-8').write(g.replace(OLD, NEW))
print(f'✓ v18b · {n} จุด · สั้นลง {len(OLD)-len(NEW)} ตัวอักษร/บอร์ด ·', os.path.getsize(P), 'bytes')
